import React, { useEffect, useState, useCallback } from 'react';
import { graphql, navigate } from 'gatsby';
import Layout from '../components/layout';
import { TagButton, TagContent, TagLink, TempContainer, PostListContainer } from '../style/tagStyle';
import { CategoryTitle, CenterPos, PostListWrapper, MoreButton, MoreButtonContainer } from '../style/blogMainStyle';
import PostItem from '../components/post-item';

const POSTS_PER_PAGE = 12;

const Tags = ({ data, location }) => {
 const tags = [{ fieldValue: 'All', totalCount: data.allMarkdownRemark.totalCount }, ...data.allTags.group];
 const [selectedTag, setSelectedTag] = useState(location.pathname.split('/')[2] || 'All');
 const [filteredPosts, setFilteredPosts] = useState([]);
 const [displayedPosts, setDisplayedPosts] = useState([]);
 const [page, setPage] = useState(1);

 const handleTagClick = (tag) => {
  setSelectedTag(tag);
  setPage(1);
  navigate(`/tags/${tag === 'All' ? '' : tag}`);
 };

 useEffect(() => {
  let newFilteredPosts;
  if (selectedTag === 'All') {
   newFilteredPosts = data.allMarkdownRemark.nodes;
  } else {
   newFilteredPosts = data.allMarkdownRemark.nodes.filter(
    (post) => post.frontmatter.tags && post.frontmatter.tags.includes(selectedTag),
   );
  }
  setFilteredPosts(newFilteredPosts);
  setDisplayedPosts(newFilteredPosts.slice(0, POSTS_PER_PAGE));
  setPage(1);
 }, [selectedTag, data.allMarkdownRemark.nodes]);

 const loadMore = useCallback(() => {
  const nextPage = page + 1;
  const startIndex = (nextPage - 1) * POSTS_PER_PAGE;
  const endIndex = startIndex + POSTS_PER_PAGE;
  setDisplayedPosts((prevPosts) => [...prevPosts, ...filteredPosts.slice(startIndex, endIndex)]);
  setPage(nextPage);
 }, [page, filteredPosts]);

 return (
  <Layout location={location}>
   <TempContainer>
    <h3>{selectedTag} 🏷️</h3>
    <TagContent>
     {tags.map((tag, i) => (
      <TagButton key={i}>
       <TagLink onClick={() => handleTagClick(tag.fieldValue)}>
        <span>{tag.fieldValue}</span>
        <span>({tag.totalCount})</span>
       </TagLink>
      </TagButton>
     ))}
    </TagContent>
   </TempContainer>
   <PostListContainer>
    <CategoryTitle>
     <div>{filteredPosts.length} 개의 글</div>
    </CategoryTitle>
    <PostListWrapper style={{ listStyle: 'none' }}>
     {displayedPosts.length === 0 && <CenterPos>포스트가 존재하지 않습니다.</CenterPos>}
     {displayedPosts.map((post) => {
      const title = post.frontmatter.title || post.fields.slug;
      return <PostItem key={post.fields.slug} title={title} post={post} />;
     })}
    </PostListWrapper>
    {displayedPosts.length < filteredPosts.length && (
     <MoreButtonContainer>
      <MoreButton onClick={loadMore}>더 보기</MoreButton>
     </MoreButtonContainer>
    )}
   </PostListContainer>
  </Layout>
 );
};

export default Tags;

// ... GraphQL 쿼리는 그대로 유지
export const pageQuery = graphql`
 query {
  allTags: allMarkdownRemark(limit: 2000) {
   group(field: frontmatter___tags) {
    fieldValue
    totalCount
   }
  }
  allMarkdownRemark(sort: { frontmatter: { date: DESC } }) {
   totalCount
   nodes {
    excerpt(pruneLength: 200, truncate: true)
    fields {
     slug
    }
    frontmatter {
     date(formatString: "MMMM DD, YYYY")
     title
     description
     category
     icon
     tags
    }
   }
  }
 }
`;
